using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Provides AI-callable tools for web searching and note-taking during research.
/// </summary>
public sealed class ResearchTools
{
    private readonly HttpClient _httpClient;
    private readonly List<NoteEntry> _notes = [];

    public ResearchTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public IReadOnlyList<NoteEntry> Notes => _notes;

    [Description("Search the web for information on a given query. Returns a list of results with titles, URLs, and snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query string")] string query,
        CancellationToken cancellationToken = default)
    {
        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  🔍 Searching: \"{query}\"");
        Console.ResetColor();

        try
        {
            var encodedQuery = Uri.EscapeDataString(query);
            var url = $"https://html.duckduckgo.com/html/?q={encodedQuery}";

            using var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.UserAgent.ParseAdd("ResearchAgent/1.0");

            var response = await _httpClient.SendAsync(request, cancellationToken);
            response.EnsureSuccessStatusCode();

            var html = await response.Content.ReadAsStringAsync(cancellationToken);
            var results = ParseSearchResults(html);

            if (results.Count == 0)
            {
                return "No search results found. Try rephrasing the query.";
            }

            return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
        }
        catch (HttpRequestException ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note with a topic label. Use this to record key findings as you research.")]
    public string SaveNote(
        [Description("Short topic label for the note")] string topic,
        [Description("The content of the note")] string content)
    {
        Console.ForegroundColor = ConsoleColor.DarkCyan;
        Console.WriteLine($"  📝 Note saved: \"{topic}\"");
        Console.ResetColor();

        _notes.Add(new NoteEntry(topic, content, DateTime.UtcNow));
        return $"Note saved under topic '{topic}'. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes. Use this to review what you've gathered before writing a summary.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        return JsonSerializer.Serialize(_notes, new JsonSerializerOptions { WriteIndented = true });
    }

    private static List<SearchResult> ParseSearchResults(string html)
    {
        var results = new List<SearchResult>();
        var span = html.AsSpan();

        // Parse DuckDuckGo HTML results by finding result links and snippets
        const string linkMarker = "class=\"result__a\"";
        const string snippetMarker = "class=\"result__snippet\"";

        int pos = 0;
        while (results.Count < 5 && pos < span.Length)
        {
            var linkIdx = html.IndexOf(linkMarker, pos, StringComparison.Ordinal);
            if (linkIdx < 0) break;

            var href = ExtractAttribute(html, linkIdx, "href");
            var title = ExtractTagContent(html, linkIdx);

            var snippetIdx = html.IndexOf(snippetMarker, linkIdx, StringComparison.Ordinal);
            var snippet = snippetIdx >= 0 ? ExtractTagContent(html, snippetIdx) : "";

            if (!string.IsNullOrWhiteSpace(title))
            {
                results.Add(new SearchResult(
                    CleanHtml(title),
                    href ?? "",
                    CleanHtml(snippet)));
            }

            pos = snippetIdx >= 0 ? snippetIdx + 1 : linkIdx + linkMarker.Length;
        }

        return results;
    }

    private static string? ExtractAttribute(string html, int startFrom, string attribute)
    {
        var search = attribute + "=\"";
        var idx = html.IndexOf(search, startFrom, Math.Min(500, html.Length - startFrom), StringComparison.Ordinal);
        if (idx < 0) return null;

        var valueStart = idx + search.Length;
        var valueEnd = html.IndexOf('"', valueStart);
        if (valueEnd < 0) return null;

        return html[valueStart..valueEnd];
    }

    private static string ExtractTagContent(string html, int startFrom)
    {
        var tagStart = html.IndexOf('>', startFrom);
        if (tagStart < 0) return "";

        var tagEnd = html.IndexOf('<', tagStart);
        if (tagEnd < 0) return "";

        // Gather text across nested tags until the closing tag
        var depth = 0;
        var content = new System.Text.StringBuilder();
        var i = tagStart + 1;

        while (i < html.Length && depth >= 0)
        {
            if (html[i] == '<')
            {
                if (i + 1 < html.Length && html[i + 1] == '/')
                {
                    if (depth == 0) break;
                    depth--;
                    var closeEnd = html.IndexOf('>', i);
                    i = closeEnd >= 0 ? closeEnd + 1 : html.Length;
                }
                else
                {
                    depth++;
                    var openEnd = html.IndexOf('>', i);
                    i = openEnd >= 0 ? openEnd + 1 : html.Length;
                }
            }
            else
            {
                content.Append(html[i]);
                i++;
            }
        }

        return content.ToString().Trim();
    }

    private static string CleanHtml(string text)
    {
        return System.Net.WebUtility.HtmlDecode(text)
            .Replace("\n", " ")
            .Replace("\r", " ")
            .Replace("\t", " ")
            .Trim();
    }
}

public sealed record NoteEntry(string Topic, string Content, DateTime SavedAt);
public sealed record SearchResult(string Title, string Url, string Snippet);

