using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using OpenAI;
using ResearchAgent;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Service setup ---
var services = new ServiceCollection();

services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));
services.AddHttpClient();

services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

var provider = services.BuildServiceProvider();

// --- Tools ---
var httpClient = provider.GetRequiredService<IHttpClientFactory>().CreateClient();
var tools = new ResearchTools(httpClient);

var aiTools = new List<AITool>
{
    AIFunctionFactory.Create(tools.SearchWeb),
    AIFunctionFactory.Create(tools.SaveNote),
    AIFunctionFactory.Create(tools.GetNotes),
};

// --- Agent ---
var chatClient = provider.GetRequiredService<IChatClient>();

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. Your job is to thoroughly research a topic the user provides.

        Follow this process:
        1. Break the topic into 2-3 key aspects to investigate.
        2. Use the SearchWeb tool to find information on each aspect.
        3. Use the SaveNote tool to record key findings as you go — include specific facts, data, and sources.
        4. After researching, use GetNotes to review everything you've gathered.
        5. Produce a well-structured summary with sections, citing your sources.

        Be thorough but concise. Focus on factual, well-sourced information.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes.",
    tools: aiTools);

// --- Run ---
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       🔬 Research Agent Ready        ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine();
Console.WriteLine($"Researching: {topic}");
Console.WriteLine(new string('─', 50));

var messages = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

var runOptions = new ChatClientAgentRunOptions
{
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 4096,
    },
    MaximumIterations = 10,
};

var session = await agent.CreateSessionAsync();

await foreach (var update in agent.RunStreamingAsync(messages, session, runOptions))
{
    foreach (var content in update.Contents)
    {
        if (content is TextContent text)
        {
            Console.Write(text.Text);
        }
    }
}

Console.WriteLine();
Console.WriteLine();
Console.WriteLine(new string('─', 50));
Console.WriteLine($"Research complete — {tools.Notes.Count} note(s) taken.");

static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrEmpty(input)
        ? "the impact of large language models on software engineering in 2025"
        : input;
}

